CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX customers_email_lower_idx ON customers (lower(email));
CREATE TABLE auth_sessions (token_hash TEXT PRIMARY KEY, customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE salons (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, location TEXT NOT NULL, address TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', rating NUMERIC(2,1) NOT NULL CHECK (rating BETWEEN 0 AND 5), image_url TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE services (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), salon_id UUID NOT NULL REFERENCES salons(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, duration_minutes INTEGER NOT NULL CHECK (duration_minutes > 0), price INTEGER NOT NULL CHECK (price >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES customers(id), salon_id UUID NOT NULL REFERENCES salons(id), service_id UUID NOT NULL REFERENCES services(id), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, payment_method TEXT NOT NULL CHECK (payment_method = 'PAY_AT_SALON'), status TEXT NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('PENDING','CONFIRMED','COMPLETED','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (ends_at > starts_at), EXCLUDE USING gist (salon_id WITH =, tstzrange(starts_at, ends_at, '[)') WITH &&) WHERE (status <> 'CANCELLED'));
CREATE TABLE booking_services (booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, service_id UUID NOT NULL REFERENCES services(id), position INTEGER NOT NULL CHECK (position > 0), PRIMARY KEY (booking_id, service_id), UNIQUE (booking_id, position));
CREATE INDEX bookings_customer_id_idx ON bookings(customer_id);
CREATE INDEX services_salon_id_idx ON services(salon_id);
